class Solution:
    def lengthOfLongestSubstring(self, s):
        seen = set(); left = best = 0
        for right in range(len(s)):
            while s[right] in seen:
                seen.remove(s[left]); left += 1
            seen.add(s[right])
            best = max(best, right - left)   # 忘了 +1
        return best

class Solution:
    def lengthOfLongestSubstring(self, s):
        seen = set(); left = best = 0
        for right in range(len(s)):
            while s[right] in seen:
                seen.remove(s[left]); left += 1
            seen.add(s[right])
            best = max(best, right - left + 1)
        return best
